        css::uno::Reference<css::uno::XInterface> ref3(new cppu::OWeakObject);

        comphelper::WeakBag<css::uno::XInterface> bag;

        bag.add(ref1);
        bag.add(ref1);
        bag.add(ref2);
        bag.add(ref2);
        ref1.clear();
        bag.add(ref3);
        ref3.clear();

        CPPUNIT_ASSERT_EQUAL_MESSAGE("remove first ref2", bag.remove(), ref2);
